@import url('https://fonts.googleapis.com/css2?family=Cabin:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500;600;700&display=swap');

/* Lazio DNA — biancocelesti sky, eagle wing white, olympic gold */
.theme-lazio {
  --bg: oklch(0.971 0.013 236.6);
  --surface: oklch(1.000 0 0);
  --surface-2: oklch(0.940 0.024 238.4);
  --fg: oklch(0.308 0.055 246.7);
  --fg-muted: oklch(0.622 0.048 240.3);
  --accent: oklch(0.654 0.120 240.4);
  --accent-fg: oklch(1.000 0 0);
  --accent-2: oklch(0.727 0.113 87.3);
  --line: oklch(0.913 0.032 236.4);
  --success: oklch(0.523 0.135 144.2);
  --warning: oklch(0.768 0.158 81.3);
  --danger: oklch(0.686 0.120 240.4);
  --radius: 0.5rem;
  --radius-sm: 0.25rem;
  --radius-lg: 0.5rem;
  --radius-pill: 9999px;
  --shadow-1: 0 1px 2px oklch(0 0 0 / 8%);
  --shadow-2: 0 6px 20px -8px oklch(0 0 0 / 15%);
  --shadow-3: 0 20px 50px -16px oklch(0 0 0 / 20%);
  --glow: 0 0 0 1px color-mix(in oklab, var(--accent) 45%, transparent);
  --border-width: 1px;
  --blur-amount: 0px;
  --font-display: "Cabin", sans-serif;
  --font-body: "Cabin", sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;
  --tracking-display: 0em;
  --label-transform: uppercase;
  --label-tracking: 0.1em;

  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}

.theme-lazio h1,
.theme-lazio h2,
.theme-lazio h3 {
  font-family: var(--font-display);
  letter-spacing: var(--tracking-display);
}

/* signature */
.theme-lazio { --font-ui: var(--font-display); }
.theme-lazio h1, .theme-lazio h2 { text-transform: uppercase; }
.theme-lazio button { text-transform: uppercase; letter-spacing: 0.06em; }

.theme-lazio { background-image: linear-gradient(180deg, #ffffff, transparent 300px); }
.theme-lazio h1 { font-weight: 700; color: var(--accent); }
.theme-lazio h2::after { content: ""; display: block; width: 4rem; height: 2px; background: var(--accent-2); margin-top: 0.4rem; }

/* depth */
.theme-lazio thead th { color: oklch(0.44 0.09 243); text-transform: uppercase; letter-spacing: 0.1em; font-size: 0.78em; border-bottom: 2px solid var(--accent); background: var(--surface); }
.theme-lazio td { border-bottom: 1px solid var(--line); }
.theme-lazio tbody tr:hover { background: oklch(0.686 0.120 240.4 / 10%); }
.theme-lazio a { color: oklch(0.50 0.11 242); text-underline-offset: 3px; }
.theme-lazio a:hover { text-decoration-thickness: 2px; text-decoration-color: var(--accent-2); }
.theme-lazio ::selection { background: var(--accent); color: oklch(1 0 0); }
.theme-lazio input:focus-visible, .theme-lazio select:focus-visible, .theme-lazio textarea:focus-visible { outline: 2px solid var(--accent); outline-offset: 1px; }
.theme-lazio kbd { background: oklch(1 0 0); border: 1px solid var(--line); border-bottom: 3px solid var(--accent); border-radius: var(--radius-sm); padding: 0.1em 0.45em; font-family: var(--font-mono); color: oklch(0.44 0.09 243); }
.theme-lazio ::-webkit-scrollbar { width: 10px; height: 10px; }
.theme-lazio ::-webkit-scrollbar-track { background: var(--surface-2); }
.theme-lazio ::-webkit-scrollbar-thumb { background: var(--accent); border-radius: 5px; border: 2px solid var(--surface-2); }
.theme-lazio ::-webkit-scrollbar-thumb:hover { background: oklch(0.55 0.11 242); }
.theme-lazio .label-caps { color: oklch(0.55 0.11 242); }
/* eagle wing: panels get a swept, feathered top edge */
.theme-lazio .themed-border { border-top: 3px solid var(--accent); border-top-left-radius: var(--radius-pill); }
.theme-lazio button:hover { transform: translateY(-1px); box-shadow: 0 6px 16px oklch(0.686 0.120 240.4 / 30%); }
.theme-lazio button:active { transform: translateY(0); box-shadow: none; }

/* alt mode: away kit (2026-27 real kit / NBA Association Edition) */
.theme-lazio.alt-mode {
  --bg: oklch(0.225 0.050 250.0);
  --surface: oklch(0.268 0.055 249.0);
  --surface-2: oklch(0.315 0.060 247.5);
  --fg: oklch(0.955 0.013 236.0);
  --fg-muted: oklch(0.700 0.045 240.0);
  --accent: oklch(0.730 0.115 236.0);
  --accent-fg: oklch(0.210 0.050 250.0);
  --accent-2: oklch(0.780 0.125 87.0);
  --line: oklch(0.72 0.07 240 / 28%);
  --shadow-1: 0 2px 6px oklch(0 0 0 / 40%);
  --shadow-2: 0 8px 24px oklch(0 0 0 / 50%);
  --shadow-3: 0 24px 56px oklch(0 0 0 / 60%);
  background-image: repeating-linear-gradient(60deg, oklch(0.85 0.08 232 / 6%) 0 3px, transparent 3px 34px, oklch(0.80 0.12 87 / 5%) 34px 37px, transparent 37px 68px);
}
.theme-lazio.alt-mode thead th { color: var(--accent); }
.theme-lazio.alt-mode a { color: var(--accent); }
.theme-lazio.alt-mode .label-caps { color: var(--accent); }
.theme-lazio.alt-mode kbd { background: var(--surface-2); color: var(--accent); border-color: var(--line); }
.theme-lazio.alt-mode input, .theme-lazio.alt-mode select, .theme-lazio.alt-mode textarea { background: oklch(0.195 0.048 250); border-color: var(--line); color: var(--fg); }
.theme-lazio.alt-mode ::-webkit-scrollbar-thumb:hover { background: oklch(0.80 0.11 235); }
.theme-lazio.alt-mode ::selection { background: var(--accent); color: var(--accent-fg); }

/* Bridge shadcn semantic variables to the theme tokens so stock shadcn/ui
   components are skinned by the theme. Scope-safe: applies inside the theme
   class only. */
[class*="theme-"] {
  --background: var(--bg);
  --foreground: var(--fg);
  --card: var(--surface);
  --card-foreground: var(--fg);
  --popover: var(--surface);
  --popover-foreground: var(--fg);
  --primary: var(--accent);
  --primary-foreground: var(--accent-fg);
  --secondary: var(--surface-2);
  --secondary-foreground: var(--fg);
  --muted: var(--surface-2);
  --muted-foreground: var(--fg-muted);
  --accent-foreground: var(--accent-fg);
  --border: var(--line);
  --input: var(--line);
  --ring: var(--accent);
  --destructive: var(--danger);
  --destructive-foreground: var(--accent-fg);

  /* Full app surface: sidebar, charts, app-level font + shadow + tracking vars.
     These are what real products (shadcn full kit, RootCX-style UI kits) consume —
     without them a retrofit looks half-themed. */
  --sidebar: var(--surface-2);
  --sidebar-foreground: var(--fg);
  --sidebar-primary: var(--accent);
  --sidebar-primary-foreground: var(--accent-fg);
  --sidebar-accent: color-mix(in oklab, var(--accent) 12%, var(--surface-2));
  --sidebar-accent-foreground: var(--fg);
  --sidebar-border: var(--line);
  --sidebar-ring: var(--accent);

  --chart-1: var(--accent);
  --chart-2: var(--accent-2);
  --chart-3: var(--success);
  --chart-4: var(--warning);
  --chart-5: var(--danger);

  --font-sans: var(--font-body);
  --font-heading: var(--font-display);
  --font-serif: var(--font-display);

  --shadow-2xs: var(--shadow-1);
  --shadow-xs: var(--shadow-1);
  --shadow-sm: var(--shadow-1);
  --shadow: var(--shadow-2);
  --shadow-md: var(--shadow-2);
  --shadow-lg: var(--shadow-3);
  --shadow-xl: var(--shadow-3);
  --shadow-2xl: var(--shadow-3);

  --tracking-normal: 0em;
}

/* Base experience: make the theme own the canvas and native elements even in
   apps that never adopted semantic classes. Scoped to the theme wrapper. */
[class*="theme-"] {
  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}
[class*="theme-"] :is(h1, h2, h3, h4) { font-family: var(--font-display); }
[class*="theme-"] :is(code, pre, kbd, samp) { font-family: var(--font-mono); }
[class*="theme-"] ::selection { background: color-mix(in oklab, var(--accent) 30%, transparent); }

/* OPT-IN HARD MODE — add "sf-enforce" beside the theme class when the host app
   bakes font/shadow/radius literals into its compiled utilities (a var bridge
   cannot beat a literal). Targeted !important, fonts and surfaces only. */
[class*="theme-"].sf-enforce { font-family: var(--font-body) !important; }
[class*="theme-"].sf-enforce :is(h1, h2, h3, h4, [class*="font-heading"]) {
  font-family: var(--font-display) !important;
  letter-spacing: var(--tracking-display) !important;
}
/* Data stays data: metrics/KPIs keep the body face with aligned lining figures.
   The display face is for headlines ONLY — never on numbers. Opt specific
   elements INTO the display face with data-sf="display". */
[class*="theme-"] :is([class*="text-2xl"], [class*="text-3xl"], [class*="text-4xl"], [class*="text-5xl"]) {
  font-variant-numeric: lining-nums tabular-nums;
}
[class*="theme-"].sf-enforce [data-sf="display"] {
  font-family: var(--font-display) !important;
  letter-spacing: var(--tracking-display) !important;
}
[class*="theme-"] :is(.sf-num, [data-sf="num"]) {
  font-family: var(--font-body) !important;
  font-variant-numeric: lining-nums tabular-nums;
}
[class*="theme-"].sf-enforce :is(button, [role="button"]) { font-family: var(--font-ui, var(--font-body)) !important; }
[class*="theme-"].sf-enforce :is(code, pre, kbd) { font-family: var(--font-mono) !important; }
[class*="theme-"].sf-enforce :is(.bg-card, [class*="card"]) {
  box-shadow: var(--shadow-2) !important;
  border-radius: var(--radius-lg) !important;
  border: var(--border-width) solid var(--line) !important;
}
[class*="theme-"].sf-enforce :is([class*="shadow-sm"], [class*="shadow-md"]) { box-shadow: var(--shadow-1) !important; }
[class*="theme-"].sf-enforce :is([class*="shadow-lg"], [class*="shadow-xl"]) { box-shadow: var(--shadow-3) !important; }
